import java.util.*;

class Solution {
    public List<List<String>> suggest(String[] products, String query) {
        String[] p = products.clone();
        Arrays.sort(p); // names sharing a prefix become one contiguous block
        List<List<String>> out = new ArrayList<>();
        for (int k = 1; k <= query.length(); k++) {
            String pre = query.substring(0, k);
            int i = lowerBound(p, pre);
            List<String> cur = new ArrayList<>();
            for (int j = i; j < p.length && j < i + 3 && p[j].startsWith(pre); j++) {
                cur.add(p[j]);
            }
            out.add(cur);
        }
        return out;
    }

    // first index whose name is >= key
    private int lowerBound(String[] a, String key) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid].compareTo(key) < 0) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

