function suggest(products, query) {
  const p = [...products].sort(), out = [];
  for (let k = 1; k <= query.length; k++) {
    const pre = query.slice(0, k);
    out.push(p.filter(w => w.startsWith(pre)).slice(0, 3));
  }
  return out;
}
